#include <stdio.h>

int main() {
    int a, b;
    if (scanf("%d %d", &a, &b) == 2) {
        for (int i = a; i <= b; i++) {
            printf("%d%s", i, (i == b ? "" : " "));
        }
        printf("\n");
    }
    return 0;
}

