code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int a = sc.nextInt(), b = sc.nextInt();
            StringBuilder sb = new StringBuilder();
            for (int i = a; i <= b; i++) {
                if (i > a) sb.append(" ");
                sb.append(i);
            }
            System.out.println(sb.toString());
        }
    }
}

